qss:
QWidget { background: #170707; color: #ffe7d6; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #170707; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #260d0a; border: 1px solid #6e2a17; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #ffe7d6; }
QLabel#SubtleLabel { color: #e69265; }
QPushButton { background: #45170e; color: #ffe7d6; border: 1px solid #6e2a17; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #5a1d10; }
QPushButton#AccentButton { background: #e34d16; border: 1px solid #ff6b24; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #ff6b24; }
QPushButton#DangerButton { background: #64131b; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #100504; color: #ffe7d6; border: 1px solid #6e2a17; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #4d1b0e; border: 1px solid #e34d16; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #260d0a; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #6e2a17; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #6e2a17; border-radius: 10px; background: #100504; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #e34d16; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #260d0a; border: 1px solid #6e2a17; border-left: 4px solid #ff6b24; border-radius: 16px; }
QFrame#UserBubbleCard { background: #4d1b0e; border: 1px solid #6e2a17; border-radius: 16px; }
